import { useState, useEffect } from 'react';
import styles from './SummaryCard.module.css';

const useFinancialData = (initialData) => {
  const [data, setData] = useState(() => {
    // Cargar datos iniciales desde localStorage
    try {
      const savedData = window.localStorage.getItem('financialSummary');
      if (savedData) {
        const parsed = JSON.parse(savedData);
        // Validar que los datos tengan la estructura correcta
        if (parsed && typeof parsed === 'object') {
          return {
            totalIncome: parsed.totalIncome || initialData.totalIncome || 0,
            totalExpenses: parsed.totalExpenses || initialData.totalExpenses || 0,
            balance: parsed.balance || initialData.balance || 0,
            currentBalance: parsed.currentBalance || initialData.currentBalance || 0
          };
        }
      }
    } catch (error) {
      console.error('Error al leer localStorage:', error);
    }
    return initialData;
  });

  // Persistir datos cuando cambien
  useEffect(() => {
    try {
      window.localStorage.setItem('financialSummary', JSON.stringify(data));
    } catch (error) {
      console.error('Error al guardar en localStorage:', error);
    }
  }, [data]);

  return [data, setData];
};

const SummaryCard = ({ 
  totalIncome: propTotalIncome = 0, 
  totalExpenses: propTotalExpenses = 0, 
  balance: propBalance = 0, 
  currentBalance: propCurrentBalance = 0 
}) => {
  const [financialData, setFinancialData] = useFinancialData({
    totalIncome: propTotalIncome,
    totalExpenses: propTotalExpenses,
    balance: propBalance,
    currentBalance: propCurrentBalance
  });

  // Sincronizar con cambios en las props
  useEffect(() => {
    setFinancialData(prev => ({
      ...prev,
      ...(propTotalIncome !== undefined && { totalIncome: propTotalIncome }),
      ...(propTotalExpenses !== undefined && { totalExpenses: propTotalExpenses }),
      ...(propBalance !== undefined && { balance: propBalance }),
      ...(propCurrentBalance !== undefined && { currentBalance: propCurrentBalance })
    }));
  }, [propTotalIncome, propTotalExpenses, propBalance, propCurrentBalance, setFinancialData]);

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${financialData.totalIncome.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${financialData.totalExpenses.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${financialData.balance.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${financialData.currentBalance.toFixed(2)}</p>
      </div>
    </div>
  );
};

export default SummaryCard;
